package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
)

// TerraformProviderAPI handles resource creation/updates for a custom Terraform provider
// This is the HTTP backend that the provider communicates with

type ResourceConfig struct {
	ID          string `json:"id"`
	Name        string `json:"name"`
	Description string `json:"description"`
	Region      string `json:"region"`
	// Internal fields - should not be settable by users
	OwnerID     string `json:"owner_id"`
	IsAdmin     bool   `json:"is_admin"`
	QuotaOverride int  `json:"quota_override"`
	BillingTier string `json:"billing_tier"`
	InternalTags []string `json:"internal_tags"`
}

var resources = make(map[string]*ResourceConfig)

func createResource(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Extract API key from header for basic auth
	apiKey := r.Header.Get("X-API-Key")
	if apiKey == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	var config ResourceConfig
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(&config); err != nil {
		http.Error(w, fmt.Sprintf("Invalid JSON: %v", err), http.StatusBadRequest)
		return
	}

	// Validate required fields
	if config.Name == "" {
		http.Error(w, "name is required", http.StatusBadRequest)
		return
	}

	if config.Region == "" {
		config.Region = "us-east-1"
	}

	// Generate ID if not provided
	if config.ID == "" {
		config.ID = fmt.Sprintf("res-%s-%d", strings.ToLower(config.Name), len(resources)+1)
	}

	// NOTE: No filtering of internal fields from request body
	// The json.Decode above will bind ALL fields including owner_id, is_admin, etc.
	// This is the mass assignment vulnerability

	resources[config.ID] = &config

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(config)
}

func updateResource(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	apiKey := r.Header.Get("X-API-Key")
	if apiKey == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	resourceID := r.URL.Query().Get("id")
	if resourceID == "" {
		http.Error(w, "id parameter required", http.StatusBadRequest)
		return
	}

	existing, ok := resources[resourceID]
	if !ok {
		http.Error(w, "Resource not found", http.StatusNotFound)
		return
	}

	// Mass assignment: decode directly into existing resource
	// This allows overwriting internal fields like is_admin, billing_tier
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(existing); err != nil {
		http.Error(w, fmt.Sprintf("Invalid JSON: %v", err), http.StatusBadRequest)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(existing)
}

func getResource(w http.ResponseWriter, r *http.Request) {
	resourceID := r.URL.Query().Get("id")
	if resourceID == "" {
		http.Error(w, "id parameter required", http.StatusBadRequest)
		return
	}

	resource, ok := resources[resourceID]
	if !ok {
		http.Error(w, "Resource not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resource)
}

func main() {
	http.HandleFunc("/api/v1/resources/create", createResource)
	http.HandleFunc("/api/v1/resources/update", updateResource)
	http.HandleFunc("/api/v1/resources/get", getResource)

	fmt.Println("Terraform provider backend listening on :8443")
	http.ListenAndServe(":8443", nil)
}
